019dbbbb-50a4-7d75-bd1c-4fc1f494834c	Frog Hops	push	intermediate	compound	\N	{quadriceps}	{calves,glutes,hamstrings}	{"Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."}	{Frog_Hops/0.jpg,Frog_Hops/1.jpg}	stretching	[0.019545216,0.04331892,-0.0039720265,-0.026125029,0.0063740257,-0.0103127975,-0.005711729,-0.001390894,-0.008975664,0.018487466,-0.013049987,-0.022342723,-0.0045967875,-0.010009434,0.11897832,-0.011404888,0.011021512,0.019588042,0.023194164,-0.0007220112,0.015543881,-0.0036066032,-0.0026719386,-0.019740628,-0.023400638,-0.0042040464,0.03049117,0.022275649,0.020443834,0.0020477646,-0.018175451,-0.00804518,0.033086974,0.023421217,0.014460665,0.0027919074,0.03526655,-0.013648717,0.0016113336,0.008702366,-0.007113379,0.0047118845,-0.0026227736,0.023292003,-0.024327094,-0.009579964,0.0023763217,0.016756328,0.021957705,0.05414785,0.003160644,0.0018427382,-0.00787174,-0.1862219,0.0026389945,0.015332156,-0.005715458,-0.027727885,-0.025846602,0.016836748,-0.00034170251,0.0058156797,-0.015322341,-0.026237931,-0.028213471,-0.013212333,0.0033657367,-0.008596474,-0.034826037,0.0045228144,0.0021451355,-0.011326371,0.012395652,-0.0020152824,-0.009042623,-0.01494353,-0.0055384915,0.027411375,0.029926777,0.019372739,0.0020770314,-0.004034625,-0.0070156106,-0.014372621,-0.007016702,-0.015465439,-0.022418717,0.0033946023,-0.010616742,-0.008440285,-0.0043768585,-0.023932086,-0.02145255,-0.004091688,0.0073917606,0.007124627,-0.0061471756,-0.018822977,-0.01642418,0.007267781,-0.018289564,-0.036706626,0.018643303,0.0034790398,7.1644485e-05,-0.01924256,0.020559827,-0.007599879,0.02707235,-0.0033243673,-0.01588856,-0.006353682,0.022967735,0.021253107,-0.0012060252,-0.14208616,0.015814504,0.020257099,-0.01769878,-