019dbbbb-50a4-7e45-fb71-1b7325ac840d	Hamstring Stretch	static	beginner	isolation	\N	{hamstrings}	{}	{"Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.","Loop a belt, band, or rope over the ball of your foot. This will be your starting position.","Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg."}	{Hamstring_Stretch/0.jpg,Hamstring_Stretch/1.jpg}	stretching	[-0.00026829928,0.033318974,0.0021907792,-0.043796893,-0.00773168,0.01750146,0.03357086,-0.0036599082,-0.012709525,0.015685752,-0.024490794,-0.0006817513,-0.023974216,-0.022305392,0.11732304,0.009742534,0.015620496,0.015257405,0.011444232,-0.011961112,-0.018396342,-0.005126846,0.009977519,-0.021049997,0.0074265357,-0.012489786,0.0068912706,0.010532575,0.03785935,0.019168345,-0.030107714,-0.004022232,-0.0043094694,0.018444052,0.019979572,0.036802877,0.025519492,-0.020340718,0.0031965761,0.025177235,0.0071123037,-0.0068006036,-0.00209902,-0.010780919,-0.017650109,0.01473007,-0.017319415,0.019935045,0.029371565,0.038971014,-0.0016489803,0.001168432,-0.010566656,-0.18392111,-0.0038970406,-0.02507446,0.0013958062,-0.012861712,0.005155126,0.013670851,-0.008451922,0.02229113,0.0019336371,-0.022824584,-0.025969265,-0.016120316,0.004536867,0.014798066,-0.019569738,0.0216663,0.0031736416,-0.011509299,0.0018207382,-0.0125647755,0.008279999,-0.0420658,-0.012966584,-0.0073439796,0.029412508,-0.0069849724,0.003712069,0.011082332,-0.0059999605,-0.0041736714,0.015177089,-0.020357821,-0.034820206,0.03582287,0.0036960552,0.004651624,0.0014802996,0.016080046,0.02498792,-0.0007727513,-0.0016772537,-0.02449632,0.009588699,0.0038118782,-0.020685043,0.010282419,-0.032067284,-0.0019435768,0.0070897234,-0.005626239,-0.010947525,-0.01272748,0.016792994,0.020847084,0.03290062,0.013701065,-0.020313932,0.0052708155,0.0013070424,0.0011522878,0.0017392138,-0.14581802,-0.01799398,0.0023648494,