019dbbbb-50a7-7722-b0f6-3ca9c3797c70	Moving Claw Series	\N	beginner	compound	\N	{hamstrings}	{calves,quadriceps}	{"This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.","Reload the quad as the leg moves back forward, attacking the ground on the next step.","Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion."}	{Moving_Claw_Series/0.jpg,Moving_Claw_Series/1.jpg}	plyometrics	[0.0053791907,0.0140848635,0.009793828,-0.04346703,-0.0047427076,0.005741852,-0.0019235929,0.011606185,-0.020428706,0.018078519,-0.047146685,0.004457406,-0.034858387,0.0073913103,0.13567701,-0.006919871,0.015805634,0.0069475695,-0.0012397036,-0.010835689,-0.026596753,-0.0042648492,0.00077041256,0.0061899903,-0.009471939,-0.021596586,0.047009196,-0.0069539915,0.024132257,0.0073973723,-0.0052141957,0.019426946,0.03717808,-0.025026197,0.01425193,0.028561538,0.007978094,-0.03789024,0.0037140818,-0.0003641097,-0.019467467,-0.005282423,0.010830457,0.01924789,-0.022750068,0.005166258,-0.0068517425,0.01097696,0.01957219,0.026254244,0.0019516052,0.008119018,-0.006823222,-0.1765096,0.0042070667,0.010340098,0.0068055587,-0.020069793,0.024984729,0.030381748,0.007623449,0.034817114,0.0061359634,-0.01570701,-0.030652558,-0.030730208,0.026955405,-0.0035255365,-0.017953359,-0.0018153125,-0.024591554,0.0087598795,0.0045076446,0.0043701767,-0.001312717,-0.025925731,-0.009041139,0.028458405,0.0040197,0.020307768,0.028261943,0.014489555,-0.011171857,-0.027858699,0.014051768,0.007136213,-0.019804046,0.008964365,0.002251896,0.00055624184,-0.005499982,-0.003799372,-0.0018211153,-0.0038170675,-0.006894929,-0.0032121665,0.0066949967,-0.004416796,-0.028557243,0.033765808,-0.0087203635,-0.0014379548,-0.0010190998,-0.013503473,0.0061791777,0.0145782055,-0.0019541879,-0.012904874,0.0035111918,0.010850551,0.0018273728,0.0057454384,-0.00228712,0.00037911136,0.009790903,-0.13606238,-0.016