019dbbbb-50a7-7605-e76f-dd6560eb4ad3	On Your Side Quad Stretch	static	beginner	isolation	\N	{quadriceps}	{}	{"Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."}	{On_Your_Side_Quad_Stretch/0.jpg,On_Your_Side_Quad_Stretch/1.jpg}	stretching	[-0.0024529716,0.014699914,0.005810478,-0.046362154,0.009365528,0.011246072,0.02992302,0.008957659,-0.024190897,0.0071501844,-0.012335689,-0.03853615,-0.012853009,-0.010909474,0.13496391,-0.015912851,0.007828276,-0.013232695,0.0045302967,0.005041416,-0.00524802,0.00878813,0.0013199829,-0.0030471878,-0.003971963,-0.0076634134,0.019197065,0.014086264,0.019507056,-0.010223837,-0.030587962,-0.0021416682,0.020511856,0.006129367,0.024220591,0.032148182,0.014074801,-0.016855774,-0.020642897,0.031706918,-0.010185067,0.018903505,-0.008520707,0.017889688,-0.033999816,0.017136987,-0.0035327321,0.011231758,0.029060291,0.047671307,-0.0051093763,0.010824521,-0.006656388,-0.1963344,0.0026051926,-0.0075472193,0.013930121,-0.0057802172,-0.0018531196,0.027424099,0.0060364236,0.031618077,-0.012741543,-0.021341024,-0.046103492,-0.025667854,-0.008759046,-0.01580402,-0.027953798,-0.0006140751,0.011524607,0.00235387,0.019276217,-0.001913844,0.006334756,-0.016216416,0.0038509842,0.028779628,0.0314973,-0.009312989,0.008128384,0.020546157,0.003202901,-0.02443812,-0.010086544,-0.010319836,-0.004042565,0.05397967,-0.009961541,0.004464059,0.0045818957,0.018941816,-0.00024389653,0.0020896243,0.0052331723,-0.01169811,0.0063629206,0.0044039018,0.004208096,0.006496537,-0.024021646,-0.023623576,0.010732404,0.010720312,0.01108736,0.00050056056,0.020142656,0.002308016,-4.5475413e-06,0.0018073862,-0.013202199,-0.0009850359,-0.00039058624,0.003724813,0.0061622057,-0.13741037,0