019dbbbb-50a8-7bfb-decf-e80efbf63ecb	One Half Locust	static	beginner	\N	\N	{quadriceps}	{abdominals,biceps,chest}	{"Lie facedown on the floor.","Put your left hand under your left hipbone to pad your hip and pubic bone.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time."}	{One_Half_Locust/0.jpg,One_Half_Locust/1.jpg}	stretching	[0.013895767,0.025007278,-0.005215735,-0.03949632,-0.0066397805,0.0019926222,-0.0062023434,0.023730531,-0.02033503,0.002714224,-0.010554238,-0.014825582,-0.010273863,-0.020547083,0.1421601,-0.019580057,-0.0024890366,0.0113520585,0.01821413,0.0042637335,-0.005857793,-0.010743384,-0.0016739357,0.0057863016,0.014353527,-0.01642163,0.013785083,0.031375006,0.026335025,-0.007865348,-0.031420384,-0.004079745,0.024521858,-0.007225447,0.006047972,0.025634443,0.038886376,-0.016014587,-0.020408297,0.013170273,0.0015233988,0.028878761,0.00070861896,-0.0044270433,-0.034586545,-0.0016981292,-0.015029596,0.01664204,0.026925573,0.0281375,0.010259033,-0.014759831,-0.005383696,-0.19352902,-0.027606731,-0.005449496,0.002610275,-0.01205819,0.0053706015,0.021067534,0.0088228,0.012164137,0.0006696339,-0.021993699,-0.029984968,-0.008033565,0.011582074,0.0018436887,-0.02869353,0.00030436515,0.023528341,-0.005891036,0.012901717,-0.013334914,0.0046614283,-0.020431535,-0.0007909472,0.023189362,0.029194936,0.012393603,0.016339848,0.008040382,-0.0008155697,-0.041192606,-0.0152292345,-0.029642904,-0.03702147,0.04478852,-0.007327583,0.024632607,-0.0029115125,-0.013940265,0.014085408,0.0105552245,0.0029899923,0.012331213,-0.008897407,0.012321704,-0.006512617,-0.011971709,-0.03548344,-0.029003548,-0.0011313454,0.030937402,-0.010654595,-0.011796463,0.008055059,0.022373978,0.015320767,0.0101041775,-0.009018512,