019dbbbb-50a8-7427-3713-4257ed2a9e04	One Knee To Chest	static	beginner	compound	\N	{glutes}	{hamstrings,"lower back"}	{"Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."}	{One_Knee_To_Chest/0.jpg,One_Knee_To_Chest/1.jpg}	stretching	[0.011192738,0.041891597,-0.006202037,-0.03715697,-0.0056390534,0.012224237,0.028701188,0.015761338,-0.027727842,-0.007663965,-0.016794464,-0.046068057,-0.012587904,-0.021920606,0.14171769,0.003060299,-0.0021163758,-0.000717619,0.013792436,-0.020025328,-0.011366723,-0.009353351,-0.0031180046,-0.014048158,0.019275855,-0.011867725,0.024691217,0.026370266,0.022130687,-0.0038284522,-0.026074974,0.0022554488,0.0007895507,-0.010483299,0.018109739,0.031110436,0.034674533,-0.014043085,-0.022857474,0.022572035,0.004830764,0.024655487,-0.019158674,0.012207531,-0.019492766,-0.010702966,-0.010048787,0.02629296,0.030382881,0.04366606,-0.010632478,0.009488579,0.0058593,-0.19215767,-0.005105671,-0.004124101,0.006931708,-0.02881758,-0.006019219,0.012492886,-0.0019422107,0.03128707,-0.0010603317,-0.014418475,-0.021092843,-0.003627074,-0.00288807,-0.005291723,-0.04278589,-0.00042577618,0.027909642,0.003353509,0.017443314,-0.0058305203,-0.006853328,-0.019816684,0.001957185,0.031634647,0.035023306,0.02051443,-0.0003985718,0.015075753,0.01628518,-0.027930856,-0.004688502,-0.03195135,-0.015441583,0.039125424,0.0014130373,0.02010279,0.020085756,0.007497326,0.012696071,0.003331674,0.019090023,0.014447546,-0.0045593297,-0.009121732,-0.00040731314,0.013110171,-0.02508315,-0.03236056,0.0042405636,0.007127924,0.01628247,-0.011908319,0.0064530494,0.011885759,0.024004681,0.01603802,-0.012433399,0.0075496323,-0.018919032,-0.015321668,0.0062020556,-0.14085682,-0.012416469,0.003010301,0.011554424,0.005891544,0.03071978,0