019dbbbb-50ab-79ed-a04a-184df4ee7c13	Seated Overhead Stretch	static	beginner	isolation	\N	{abdominals}	{}	{"Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."}	{Seated_Overhead_Stretch/0.jpg,Seated_Overhead_Stretch/1.jpg}	stretching	[0.010179207,0.03165904,0.0018126371,-0.056432933,0.020282364,0.004368678,0.015128071,0.020444343,-0.032576542,0.0074289213,-0.022507802,-0.023633722,-0.007381541,-0.020527763,0.11164424,-0.018295059,0.0041572815,0.003890381,0.015703015,0.008986116,0.006966584,-0.02367869,0.005031539,-0.01677483,0.0009167099,-0.031474087,0.038268127,0.0035045156,0.033277757,-0.0036449502,-0.018748282,-0.011220129,0.0064278143,0.025831629,-0.009865957,0.011435196,0.05725686,-0.020293474,-0.016487937,0.007947566,0.022625914,0.011249934,-0.011608003,-0.0040380997,-0.02718428,0.0022643902,-0.008143894,0.024688609,0.023015754,0.039479867,-0.011701026,-0.005609739,-0.027187629,-0.19365732,-0.0069108987,0.004096848,0.021424994,-0.026466751,-0.013774677,0.017516442,-0.004938194,0.015776355,-0.005378663,-0.018238395,-0.021455659,-0.0074148057,-0.0214246,-0.017205106,-0.033975944,0.022052344,0.0077909734,-0.012477835,0.028401172,-0.014103199,0.011338733,-0.022990119,-0.0053376285,-0.0003812986,0.016165465,-0.0039506513,-0.007453622,0.0014837433,2.5185938e-05,-0.021044757,-0.009074811,-0.007577376,-0.025814015,0.0589504,-0.0015168666,-0.004141702,0.0055105602,-0.002801034,0.013488176,-0.009816302,0.011567329,0.004932269,-0.011828968,-0.018068872,-0.0036334228,-0.0051537096,-0.04456603,-0.004216277,0.001888668,0.010052376,0.0027108623,-0.011467246,0.012966842,-0.020376777,0.012716649,0.027624495,-0.0017564595,0.014746882,0.007480731,0.010210608,0.009250012,-0.14222962,-0.015206596,-0.