019dbbbb-50ab-735f-b1b2-83dcd9052ad5	Side-Lying Floor Stretch	static	beginner	\N	\N	{lats}	{}	{"First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).","Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides."}	{Side-Lying_Floor_Stretch/0.jpg,Side-Lying_Floor_Stretch/1.jpg}	stretching	[0.003544467,0.040471844,-0.008861031,-0.019206692,0.008291887,0.0009791327,0.02635896,0.025835883,0.0019822705,0.012204833,-0.023603164,-0.03236794,-0.020480527,0.012209819,0.11472615,0.0007151723,-0.0014256528,-0.002576605,-0.012216276,0.0025183186,0.015641209,-0.011864144,0.018494975,-0.018317727,0.01251112,-0.018493462,0.039801754,-0.0027946294,0.03546437,-0.015919229,-0.011757183,-0.0050948467,0.02318691,-0.0009717701,0.024815554,0.014676343,0.023901135,0.003748093,-0.012325616,0.016697668,0.006512169,0.031117339,0.001521559,0.0044444394,-0.026261982,0.012623725,0.0099187605,0.011277032,0.00809534,0.05585118,0.0056127408,0.0010261877,-0.0005845667,-0.1972934,-0.0071433787,-0.008010167,-0.0064702844,-0.013839664,-0.017882708,0.021908268,-0.003207636,0.018631177,0.0006766413,-0.015066809,-0.027918853,0.00094024074,-0.000626828,-0.011574398,-0.03327317,0.008199371,0.012150575,0.020234177,0.017769584,-0.008898557,0.013084665,-0.020459518,0.012394412,0.001785056,0.01301734,0.009553232,0.0013327642,0.0025735577,-0.0011755816,-0.015153287,-0.010096135,-0.0035785725,0.014712578,0.034154963,-0.0006315596,0.019396743,-0.0085655125,-0.0014525431,0.019443123,0.0083649345,-0.013654174,-0.002543391,0.0027297954,-0.0074225324,0.016549805,0.006779782,-0.025941046,-0.01471476,-0.0070453724,0.021021113,-0.0015586867,0.001896539,0.0042812894,-0.0041867173,-0.001355778,0.007531808,-0.015828107,-0.020171762,-0.011742611,0.0064976434,-0.0026950769,-0