019dbbbb-50ab-7201-9c1a-1b35f726bab6	Side Lying Groin Stretch	static	beginner	isolation	\N	{adductors}	{hamstrings}	{"Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."}	{Side_Lying_Groin_Stretch/0.jpg,Side_Lying_Groin_Stretch/1.jpg}	stretching	[0.008034907,0.039549526,0.0016643823,-0.040078864,-0.0015088851,0.006158593,0.008987942,0.013496179,-0.006342129,0.012208523,-0.020225035,-0.0076966947,-0.0039025315,-0.018631766,0.12931702,-0.008174255,-0.0043179574,0.0233069,-0.0034965067,-0.004604612,0.013816555,-0.017676055,-0.007214577,-0.0021320917,0.0015287714,0.0030761089,0.015785724,0.0182259,0.023788864,0.007512463,-0.028285312,-0.0008337681,0.02432645,0.0053108903,0.025688995,0.018442001,0.03696323,-0.012803922,-0.020754796,0.012847934,-0.008570675,0.02348013,-0.005389674,0.015733251,-0.012001223,0.023409076,0.01973158,0.0066870986,0.010334418,0.03188841,0.004939764,-0.000393451,-0.0046983794,-0.1921769,0.0017204251,0.0028395643,-0.004495704,-0.023635363,-0.01670775,0.019348843,0.0016310187,0.031083584,0.003791603,-0.012397127,-0.036697254,-0.021538418,0.004130312,-0.00592803,-0.030221667,-0.0065961047,0.0060240594,0.009603204,0.011453356,0.00078786694,-0.0014557602,-0.015048661,0.0024472468,0.024273729,0.03098662,-0.0024287135,-0.008650906,0.00832653,0.0064296583,-0.02469345,-0.018204894,-0.011673765,0.012768847,0.03658649,-0.0057453313,-0.0068334625,-0.0023426001,0.018883284,0.010889789,0.0237006,0.017773803,-0.009770051,0.0061643533,-0.008190283,0.011674632,0.01344206,-0.021292698,-0.00891241,-0.0033027856,-0.0014810073,0.005604605,-0.003467136,0.011701622,0.0017268773,0.01265787,0.006388866,0