019dbbbb-50ab-7f06-ca73-ae54907371f6	Side Wrist Pull	static	beginner	isolation	\N	{shoulders}	{forearms,lats}	{"This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.","Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don't pull too hard on the shoulders joint. Switch sides."}	{Side_Wrist_Pull/0.jpg,Side_Wrist_Pull/1.jpg}	stretching	[-0.0020528983,0.016189978,-0.0036355918,-0.023780532,-0.00043425555,0.03918361,0.011356763,0.01737451,-0.023850298,0.018499795,-0.027936175,-0.01849079,-0.00056256173,-0.0032375026,0.11940271,-0.01689692,-0.004961114,-0.0019241916,0.008787046,0.018233309,-0.0030830437,-0.0062557063,0.022163628,-0.018699,0.0103305355,-0.032261267,0.0213619,-0.0035454317,0.05225209,0.013082556,-0.02431707,-0.011735248,0.010580923,0.001388404,0.0036081553,0.002745396,0.027406033,-0.0080212625,-0.020103488,0.018400295,-0.0035287016,0.0013107947,-0.00061652676,-0.006425154,-0.012040067,0.0013379301,-0.0017003203,0.007438752,-0.008699565,0.056436554,0.0016031433,-0.009043734,-0.02169486,-0.20367868,-0.019364532,0.014263553,0.01871612,0.0069780955,-0.024977028,0.027881013,0.018696906,0.024190182,0.015171887,-0.023025077,-0.043895673,-0.023903295,-0.008423232,-0.0049391496,-0.006761563,0.0035533654,0.014797675,-0.008124741,0.021117557,-0.0078042513,0.0074730134,-0.028731214,-0.004137246,0.00033565998,0.019286582,-0.0057785055,0.0020650811,-0.016064534,0.00031736674,-0.024882533,-0.00995293,0.011154977,0.0050689927,0.0313085,0.0076614395,0.021725388,-0.011921409,-0.0018114418,0.012760737,-0.0042144074,-0.0119944075,0.0039800038,0.0014962704,-0.008593777,0.0072290776,-0.001026962,-0.0173998,-0.0017191006,-0.0049844445,0.01254426,-0.0004971537,-0.02008341,0.009434322,0.0024056789,-0.005246328,0.027403813,-0.008402844,0.004395646,-7.24