019dbbbb-50ab-7512-b341-fe5b0eb54c71	Sit Squats	push	beginner	\N	\N	{quadriceps}	{abductors,glutes,hamstrings}	{"Stand with your feet shoulder width apart. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions."}	{Sit_Squats/0.jpg,Sit_Squats/1.jpg}	stretching	[0.0031458598,0.0035570213,-0.0034744544,-0.03844251,-0.01705099,-0.012825906,0.00053728523,6.352136e-05,-0.02161503,0.006933257,-0.031578396,-0.023848116,-0.022828417,-0.0039636903,0.12008494,0.009968336,-0.008789839,0.007890259,0.013477806,-0.004204357,0.0008542891,0.009117482,-0.006648476,-0.017269546,-0.016721394,-0.0065620537,0.034126274,0.009641591,0.044533186,0.014628784,-0.014370556,-0.004260169,0.039850935,0.021806916,0.011643145,0.029724875,0.037292935,0.0028872138,0.003071088,0.0028814585,-0.014549799,-0.011260551,-0.023376005,0.02143008,-0.023518272,0.0015780961,-0.00043914584,0.023657877,0.0041308603,0.038034774,-0.009919522,-0.003338342,-0.0164552,-0.18620919,0.0016054802,0.010129176,0.0043558683,-0.028025882,0.0016806815,0.017770596,-0.0200322,0.01232906,-0.012258061,-0.01959031,-0.024955694,-0.033562087,0.013122906,0.0011041185,-0.021989804,0.016305786,0.0063177613,-0.01580586,0.02594294,0.006167536,-0.0036045194,-0.008337471,-0.008310691,0.044451233,0.0211192,-0.0028103692,0.0074818456,-0.018905032,-0.008952452,-0.0036955625,-0.008876721,0.0015985256,-0.018708639,0.011493263,-0.0024094682,-0.008977263,-0.018282497,-0.0075534927,-0.014703236,-0.010355726,0.008084971,0.0066545196,-0.000594156,-0.0150596555,-0.015898423,0.0201468,-0.02260439,-0.01607987,0.013715848,0.008793365,-0.00050731807,-0.011074478,0.019537013,-0.01663832,0.024660436,0.0061739776,-0.0025186143,-0.0066595953,0.0073863454,0.010658112,-0.004099505,-0.14079776,-0.0040672426,0.0161