019dbbbb-50ad-74b7-d19b-a9cd89b68039	Spinal Stretch	static	beginner	isolation	\N	{"middle back"}	{lats,"lower back",neck,traps}	{"Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."}	{Spinal_Stretch/0.jpg,Spinal_Stretch/1.jpg}	stretching	[0.010082549,0.022099972,0.009586956,-0.04292964,0.025509665,0.017030764,0.022809455,0.0019845667,-0.032280732,0.007525197,-0.01090877,-0.019812893,-0.0058338176,0.0063680294,0.1171195,-0.013876011,-0.003980672,-0.00021735836,0.015301328,-0.026515484,0.0069947448,-0.015722312,0.013720171,-0.020990944,0.0012973701,-0.022056596,0.044406302,-0.005824226,0.05334181,0.010464067,4.379397e-05,-0.004684463,0.00997319,0.0026010098,0.0045469706,0.012586345,0.0309492,-0.0025282882,-0.01782205,0.012449084,0.00023842069,-0.0016460489,-0.014670298,0.0037678783,-0.022332981,-0.020976257,-0.012033095,0.028202968,0.005123691,0.043765556,-0.0062638363,0.004063762,-0.037434813,-0.20340814,0.0006767487,0.0056499657,-0.010855925,-0.0391105,-0.02583397,0.022814617,0.006759015,0.013077248,-0.013290096,-0.012876461,-0.006987903,-0.008312909,0.0047750906,-0.0035337768,-0.043445263,0.020078894,0.019201396,-0.010152396,-0.004267713,-0.00686323,0.0076004667,-0.008569504,0.001977048,0.027119122,0.043045275,-0.0015009054,0.010974382,-0.012981589,0.002631311,-0.009707885,-5.776262e-06,-0.012909948,-0.0049199676,0.048015464,0.020146305,0.011698791,-0.014072657,0.001116402,0.008513997,-0.0031882941,-0.009065677,-0.008370773,-0.011884147,0.00030589863,-0.0137556745,-0.0023293113,-0.031358887,-0.0116638355,0.011970023,-0.021663405,0.0044792118,-0.019019404,0.0007760311,-0.017429277,0.017987553,0.0036044263,-0.0011759435,0.009156295,-0.0050