019dbbbb-50ae-758f-c8f2-6662556a70df	Standing Gastrocnemius Calf Stretch	static	beginner	\N	\N	{calves}	{hamstrings}	{"Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.","Support your weight on your left leg and place your left hand on your left thigh.","Pull your right toes toward your knee until you feel a stretch in your calf."}	{Standing_Gastrocnemius_Calf_Stretch/0.jpg,Standing_Gastrocnemius_Calf_Stretch/1.jpg}	stretching	[0.0021263922,0.043200374,-0.012861085,-0.022587942,-0.015036303,0.043717653,0.027685672,-0.0019874005,-0.027678732,0.014236719,-0.03534266,-0.031080548,0.0076142848,-0.011490464,0.1254079,-0.036617965,0.01775965,0.03374666,0.016965957,-0.008316425,-0.01183078,-0.0025911827,0.0053217816,-0.0016373126,0.0063102418,-0.00096254353,0.04284616,-0.005225388,0.03232277,-0.008321946,-0.02050068,0.0075679994,0.01504451,0.014037382,0.026357884,0.012295187,0.018580368,-0.020420881,0.0048853667,0.028235259,-0.01444495,0.011865936,-0.011733321,-0.028126663,-0.0045521306,0.027827412,0.009116747,0.004523256,0.022397535,0.03365403,0.021044819,0.00014864498,-0.009169588,-0.20430185,-0.01551281,0.0014162388,0.009504737,0.0057548834,-0.018122809,0.026479192,0.0289619,0.030826198,0.008667835,0.013518608,-0.028911794,-0.015905958,0.0049904087,-0.0007096603,-0.008290031,-0.008680091,0.0060181757,-0.0016944024,0.0017952783,0.013591854,-0.011523674,-0.021698076,0.0061307033,0.004769909,-0.00016771341,0.009748533,-0.0067677693,-0.018691175,-0.0023200898,-0.036629613,0.012765741,-0.029836109,-0.0042107105,0.0339807,0.0042147744,0.009695159,0.01538847,0.0055424,0.020152165,0.010453756,-0.009433977,-0.003205326,0.007087199,-0.0035929608,0.0027456593,0.006526205,-0.017453114,-0.013978252,-0.00095712184,-0.0062182792,-0.0096482895,-0.0034370597,0.029896379,-0.015611679,0.027269382,0.011230315,-0.0139179705,-0.0012305073,-0.0030095803,