019dbbbb-50ae-7276-dccb-1b6e0b235f90	Standing Hamstring and Calf Stretch	static	beginner	\N	other	{hamstrings}	{}	{"Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."}	{Standing_Hamstring_and_Calf_Stretch/0.jpg,Standing_Hamstring_and_Calf_Stretch/1.jpg}	stretching	[-0.010305725,0.03060701,-0.005817818,-0.04139474,-0.0072133304,0.031580478,0.027854208,0.0022562211,-0.013955918,0.015175908,-0.03359441,-0.026894953,-0.0036802832,-0.02349304,0.109567344,-0.02384147,0.0359251,0.01059596,0.028461961,-0.007977056,-0.035077274,0.010890313,0.009792329,-0.008600402,-0.0031172726,-0.005061147,0.024843853,0.02054104,0.045882702,0.007078075,-0.025017513,-0.005087863,0.004580504,0.011876397,0.014017771,0.016558973,0.034339573,-0.014134213,-0.008191595,0.023870531,-0.022379508,0.0016295792,-0.0010807253,-0.0071853627,-0.02406756,0.015163612,-0.009909885,0.013672127,0.021989936,0.052058447,0.011743235,0.008109009,0.004223566,-0.19641249,-0.010736579,-0.0059651993,0.013982703,-0.0049874126,-0.020653224,0.0097049745,0.0059237587,0.020018723,0.0036769696,-0.0075138435,-0.02405,-0.02635048,0.012197309,0.002621793,-0.019674428,0.010502437,0.0058795507,-0.009781289,0.0016086486,-0.015773598,0.004425144,-0.036852345,-0.015084804,0.00490315,0.019880205,0.006934392,0.0086438125,0.0017965717,-0.011254943,-0.008260257,0.008741369,-0.02952543,-0.03022433,0.027091216,0.013080893,0.008623008,0.00026924544,0.008226351,0.022819063,-0.0012753111,-0.0062055215,0.0011207273,0.005679066,-0.0017448222,0.0007759358,0.003872895,-0.023475518,-0.0028560818,-0.009527852,-0.0030027258,-0.0129723055,-0.009040466,0.019079892,0.004527307,0.033447098,0.022867894,-0.022442672,-0.0041027465,0.00275133