019dbbbb-50ae-73f1-8304-fffb5e5be912	Standing Hip Flexors	static	beginner	isolation	\N	{quadriceps}	{}	{"Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can't get a thorough, deep stretch in this position, however, because it's hard to relax the hip flexor and stand on it at the same time. Switch sides."}	{Standing_Hip_Flexors/0.jpg,Standing_Hip_Flexors/1.jpg}	stretching	[0.010911447,0.022647606,-0.013083586,-0.039183944,-0.012801496,0.0021054384,0.007008586,-0.002709149,-0.014692785,0.010472649,-0.0030535776,-0.027557109,0.0064236657,-0.025008947,0.13297594,-0.017362814,0.0042269747,0.02894705,0.024311356,0.008478075,0.016470948,0.0072577484,0.009229071,0.01630026,-0.0029182355,0.017136814,0.009564141,0.0004258663,0.021956876,-0.012578686,-0.015269476,0.008124173,0.02036385,0.010816951,0.008054144,0.027957983,0.02462531,-0.013601483,-0.0115605015,0.010139226,0.0045487043,0.022439374,-0.019230658,-0.0071551283,-0.030631403,-0.0025357467,0.016937751,0.016345838,0.019515824,0.034520146,-0.016887315,0.016045883,0.0013072183,-0.19929397,-0.007725069,0.017995546,0.018018525,-0.022879774,-0.013204688,0.011136739,-0.008475416,0.01703407,-0.011554947,-0.025725495,-0.027477203,-0.0076907217,-0.0027273197,-0.01641277,-0.031980768,0.02482824,0.0063833403,-0.010243671,0.01985154,-0.006485075,-0.016216468,-0.02586422,0.0028056288,0.027692223,0.03693044,-0.0023823152,-0.0048950478,-0.0006711943,-0.016884116,-0.029729843,-0.0044410382,-0.0079188915,-0.016770696,0.018815985,-0.004295609,0.014537992,0.029636022,0.012868968,-0.0023785862,-0.009304518,-0.00361332,-0.0074849757,-0.007926998,0.005971134,0.0034750558,-0.025233902,-0.027285725,-0.011369046,0.0019790137,0.008701993,0.009925123,-0.008450242,0.0070223426,-0.010076213,0.0075088213,-0.0084158,-0.015551544,-0.005006976,-0.002396593,-0.0027112602,0.01277994,-0.13013521,0.00047794895,0.013620745,