019dbbbb-50ae-70b1-3c76-7afbbb87b30c	Standing Lateral Stretch	static	beginner	\N	\N	{abdominals}	{}	{"Take a slightly wider than hip distance stance with your knees slightly bent.","Place your right hand on your right hip to support the spine.","Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.","Keep your weight evenly distributed between both legs (don't lean into your left hip). Switch sides."}	{Standing_Lateral_Stretch/0.jpg,Standing_Lateral_Stretch/1.jpg}	stretching	[0.01815083,0.04634461,-0.0028440768,-0.024406148,0.00072627846,0.011369305,0.0040911203,0.00397886,-0.023686998,0.010659211,-0.016207904,-0.034939457,0.01587835,-0.0049001495,0.10727486,-0.017765384,0.01369402,0.009878037,0.005962327,-0.005897321,0.013566463,-0.008797269,0.010581096,-0.0028202455,-0.023351215,-0.012600727,0.032181963,-0.016914181,0.029174984,0.0072389045,-0.020827055,0.0018914258,0.017491868,0.020756332,0.0057923915,0.0053322613,0.029840596,-0.015016707,-0.010519263,0.007894332,0.0012088038,0.013508807,-0.016398424,-0.022458632,-0.026901571,0.0036104047,0.006107457,0.031933263,0.00928427,0.040842123,-0.011976793,0.007749466,-0.019749885,-0.20059088,-0.018542746,0.0121949045,0.0027154628,-0.00785133,-0.016277509,0.0267726,0.021524891,0.009053231,0.015717817,-0.017571127,-0.022651805,-0.013268662,0.010861837,-0.03386605,-0.030199489,0.013943563,0.005423984,0.011958115,0.025485108,-0.0027698753,-0.0046579577,-0.028062647,0.0068540038,0.0073081683,0.021896884,-0.011666036,-0.004391844,0.009095671,-0.006316811,-0.01186698,-0.010024894,-0.019794203,-0.0011049821,0.022222845,-0.008388248,-0.0015478217,-0.00776846,0.02405667,-0.0016055536,-0.0021808296,-0.00242303,-0.014687884,0.008052889,0.0031782673,-0.010392773,0.004982922,-0.01141345,-0.03006244,-0.008062435,0.019055493,0.0009816728,-0.023226324,0.010175161,-0.016920049,0.01073794,0.0031156994,0.0023284692,-0.0036076484,0.01009003,0.007854353,0.002588