019dbbbb-50ae-7141-e0c0-aec2ebf7316f	Standing Elevated Quad Stretch	static	beginner	\N	other	{quadriceps}	{}	{"Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides."}	{Standing_Elevated_Quad_Stretch/0.jpg,Standing_Elevated_Quad_Stretch/1.jpg}	stretching	[-0.012970895,0.033351496,-0.017275967,-0.036553882,-0.0061074942,0.012449367,0.025921293,0.0065004467,-0.022636773,0.0062460043,-0.026937274,-0.050916474,0.00822912,-0.016793238,0.11517536,-0.024117578,0.021765448,0.01608387,0.00829861,-0.009201194,-0.0056681135,0.0019882626,0.020268967,0.00031819212,-0.012770488,-0.0036964067,0.018671338,0.005355067,0.025332697,-0.0139881335,-0.019577717,-0.0007764633,0.014825094,0.0072720437,0.019763496,0.01078398,0.031172287,-0.009346387,0.0005184079,0.02486026,-0.007274734,0.028345304,-0.008005687,-0.012815365,-0.027586317,0.004788589,-0.0005567607,0.008700838,0.033516537,0.043921836,-0.00043082022,0.00044161055,-0.017178314,-0.20161201,0.0061886855,-0.00256051,0.001313882,-0.0060222787,-0.0067061093,0.03028165,0.015726808,0.009016654,-0.0032070896,-0.0104334485,-0.03911186,-0.029613111,-0.0006158817,-0.02756275,-0.015987707,0.0017334188,0.004259438,-0.007490396,0.020442132,0.00587812,-0.013137577,-0.028206015,-4.402143e-05,0.021091199,0.024601707,-0.0022759154,-0.008158302,-0.008179062,-0.008712038,-0.020579657,-0.0034386115,-0.014947811,-0.018453669,0.044707697,-0.0021491088,-0.006511294,0.017386897,0.0033281695,0.013847941,-0.005178533,0.00061516586,-0.0025436846,0.003888926,-0.0008809499,-0.0048975847,0.00062894094,0.002816273,-0.0067340345,0.009581268,0.0052898717,0.0065923063,0.009888466,0.016281402,-0.00851867,0.011888082,0.003289444,-0.011158989,-0.011430868,0.0013037295,0.018681062,0.014147