019dbbbb-509f-7326-cb1f-bd163e5714ac	Alternate Leg Diagonal Bound	push	beginner	compound	\N	{quadriceps}	{abductors,adductors,calves,glutes,hamstrings}	{"Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."}	{Alternate_Leg_Diagonal_Bound/0.jpg,Alternate_Leg_Diagonal_Bound/1.jpg}	plyometrics	[0.025691736,0.015469525,0.007343214,-0.036029305,-0.015749991,-0.0027680653,0.012420082,-0.02069963,-0.0072213295,-0.011167779,-0.005107831,-0.011088246,0.005687902,-0.009619764,0.110255644,-0.029977197,0.019998541,0.017887276,0.007303495,-0.0119414525,0.0033033357,-0.005477494,-0.004554929,-0.00018560688,0.011883706,0.00015990046,0.03274832,0.008923872,0.025759934,-1.87422e-05,-0.0051220166,0.0040699644,0.024325125,0.013157461,0.019623004,0.0048923334,0.0063961493,-0.0053752465,0.0039908844,0.017131362,-0.014151938,-0.0032862998,0.00028452868,0.01675011,-0.006172811,-0.0066190176,-0.0126672955,0.014668317,0.009038587,0.036825266,0.0075513115,0.024878668,-0.018575385,-0.18726332,-0.0018835736,0.008657406,-0.02223667,0.0006983378,-0.017468875,-0.014894979,-0.009472829,0.02297288,-0.0019248842,-0.034521256,-0.014660624,-0.015535294,-0.0026890365,-0.019294487,-0.04933407,-0.00624308,0.0060899076,-0.006493227,-0.0015207515,-0.0018091176,-0.0049847728,-0.024395319,-0.017570574,0.002989146,0.023387985,0.016683837,-0.006212955,-0.0031551863,0.0053234575,-0.018740278,-0.0014366537,-0.015420042,-0.014097053,0.020194849,-0.02205809,0.001478076,-0.0025474543,0.0058250153,0.0029331092,0.010223739,-0.006166418,-0.0029974063,0.007205976,0.00037354423,0.004487913,0.011594991,-0.005472598,-0.021733101,-0.0036559675,0.0065105413,0.010089716,-0.009345407,0.01973737,-0.0056945686