019dbbbb-509f-72ab-d915-67ae4d94c0d6	Ankle On The Knee	static	beginner	\N	\N	{glutes}	{}	{"From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."}	{Ankle_On_The_Knee/0.jpg,Ankle_On_The_Knee/1.jpg}	stretching	[0.012451765,0.03059074,-0.007813049,-0.042733002,-0.0061139013,0.011957247,0.019928548,0.022256918,-0.035743408,0.00060476223,-0.008712045,-0.03668131,0.0053790286,-0.0019252191,0.10820695,-0.0070142318,-0.0049266694,0.01750702,0.0069224304,-0.011083029,-0.0007803203,0.00434695,-0.0034082718,-0.009044645,0.017366963,-0.013912015,0.025641108,0.0036409455,0.036088083,0.0017039165,-0.012266849,-0.012850055,0.014178798,0.0019762993,0.012666966,0.018254148,0.034542717,-0.018934658,-0.015037324,0.016392415,0.0052106986,0.022026353,-0.006860385,0.020131463,-0.030680794,0.004725833,0.004826856,-0.00057459145,0.021533236,0.036556464,0.0252176,0.0072841556,-0.0040922523,-0.19583373,-0.00022130721,-0.0026779356,0.018510647,-0.025638854,-0.021072434,0.01501094,-0.013139774,0.01798885,-0.0015731626,-0.039696194,-0.011812499,-0.022679867,-0.013706072,-0.01590268,-0.042189423,0.029781625,0.01580562,-0.008695986,0.01427657,-1.0660652e-05,0.0058932523,-0.021975106,0.004015468,0.02027117,0.02758411,0.009958169,0.006542557,0.008113414,-0.012568512,-0.008101864,-0.008682449,-0.026125494,-0.018716326,0.037749816,0.008571262,0.019085737,-0.0029000118,-0.0051819882,0.028154276,0.0014928515,0.02824522,0.023386488,-0.0164574,-0.014500264,-0.003151994,0.010819344,-0.02610362,-0.022486053,-0.00030870113,0.006437207,0.0063451296,-0.015569087,0.021907425,0.0017886898,0.013669272,0.015898418,-0.019655192,-0.0096897045,-0.005265905,-0.0008795903,0.021860456,-0.1436847,-0.0010351605,0.0014972219,0.0052431636,0.0028382044,0.0141157145,-0.00209995,0.019164015,0.0