019dbbbb-50a2-742d-920a-a49f9318e0c9	Carioca Quick Step	\N	beginner	\N	\N	{adductors}	{abdominals,abductors,calves,glutes,hamstrings,quadriceps}	{"Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."}	{Carioca_Quick_Step/0.jpg,Carioca_Quick_Step/1.jpg}	plyometrics	[0.0027506608,0.0037572777,-0.031911317,-0.027440479,-0.011921264,0.0032274635,0.014890714,0.009359406,-0.025880016,-0.01004773,-0.02192649,-0.012018933,-0.0041657663,-0.012836796,0.1378473,-0.0049292995,0.0079059405,-0.011751923,-0.0024634772,-0.010651305,-0.026013328,0.010959148,0.019363053,0.006020079,0.006739792,-0.0030892,0.039801847,-0.009028147,0.01213679,0.009729619,-0.008031889,0.016212272,0.06646876,0.022360733,0.027074004,-8.43219e-06,0.0011247647,-0.026867086,-0.030761559,0.024687342,0.0007089744,-0.018326638,-0.020366563,0.018733695,-0.016290171,-0.0013005671,0.02033669,0.00826124,0.0009292322,0.042029206,0.007284744,0.016292155,-0.015779248,-0.20834656,0.002299598,0.0111823045,0.00581846,-0.01018269,6.5280765e-05,0.016754579,0.022804394,0.02363189,0.009325112,-0.005181755,-0.025263187,-0.00037399094,0.005764827,-0.0087001715,-0.011238533,0.02408752,0.027480094,-0.021805273,0.01390488,0.013970436,-0.008980056,-0.01707882,0.017115273,0.014211051,0.00049790833,0.017047822,-0.004633751,-0.019295912,0.003969255,-0.04310102,-0.006014732,-0.009901844,0.0033253483,0.013957878,-0.008889771,-0.0039796503,-0.006711587,-0.022620546,-0.019144064,0.0075177653,-0.0014895443,0.0008593021,0.029485278,-0.0111505,-0.0064779357,0.014096366,-0.025562538,-0.018503089,0.027454287,0.005335608,0.0069338824,-0.015708962,0.016635178,0.004351305,0.005039836,0.005253975,-0.01796745,-0.0042675924,-0.0010038322,0.027471596,0