019dbbbb-50a2-74f6-7b04-f4ca101c81b1	Child's Pose	static	beginner	\N	\N	{"lower back"}	{glutes,"middle back"}	{"Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \\"breathe\\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."}	{Childs_Pose/0.jpg,Childs_Pose/1.jpg}	stretching	[0.01606255,0.020940717,-0.008293405,-0.033682007,0.009632496,0.020852696,0.0040950943,0.022643158,-0.0013639983,0.0037213778,-0.016538994,-0.03653954,0.0024691124,0.008791281,0.13995944,0.010837573,-0.007181156,0.029269004,-0.0025127348,-0.022750292,0.010927246,-0.005705891,0.0036827605,-0.0076801744,-0.019845242,-0.011658243,0.018948764,0.0012095316,0.05629757,-0.004926653,-0.010093401,0.0006201413,0.009252443,0.008281024,-0.011110874,0.037819687,0.02739028,-0.024355154,-0.0048133763,0.020761361,0.028156113,0.029128103,-0.0025287354,-0.0254775,-0.015605354,-0.024770359,0.0060295206,0.033794902,0.012623243,0.04275685,0.0030255099,0.019521654,-0.041608088,-0.20324443,0.0033102576,0.009730116,0.008660447,-0.012492231,-0.009369507,0.015881475,-0.0012428578,0.013862877,-0.012544451,-0.00447892,0.01718606,0.006805528,0.008108561,0.004657946,-0.028278368,-0.003705747,0.009172681,0.0006638633,0.013745272,0.001182484,0.0014241808,-0.018215576,-0.0055061164,0.019700276,0.0336709,0.014813376,0.0020196259,0.017229939,-0.02079587,-0.014932009,0.026553823,-0.02601587,-0.014690499,0.034480836,0.0015440887,0.0053672916,0.000114516355,-0.011521939,0.020883,0.021431625,0.025085706,-0.003249916,0.007810176,0.020753173,-0.014134368,0.009616958,-0.0328718,-0.016376039,0.009668801,0.01092434,0.023634847,-0.00042879328,0.0136624845,-0.0143400105,0.015164181,-0.004547681,0.005404413,0.0065644844,-0.01573267,0.016136313,0.0045522996,-0.13832703,0.008182