019dbbbb-50a2-76b4-27e4-0be3c0410ff1	Dancer's Stretch	static	beginner	\N	\N	{"lower back"}	{abductors,glutes}	{"Sit up on the floor.","Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides."}	{Dancers_Stretch/0.jpg,Dancers_Stretch/1.jpg}	stretching	[-0.008302006,0.03205893,0.0011998558,-0.041761134,0.013065942,0.0021626516,0.014361834,0.008148947,-0.02878779,-0.01534791,-0.024698243,-0.02391764,-0.008725812,-0.014230837,0.14188445,0.0042254264,0.011745467,-0.00073492335,0.0048941174,-0.009902834,0.008590458,-0.0071186423,0.007589824,-0.013502009,0.0041997647,-0.01973958,0.026388299,0.012360568,0.03638621,0.01841884,-0.009461179,-0.0050380644,0.027667033,0.010168624,0.008386253,0.01766572,0.036167666,0.0051755076,-0.007185759,0.010812986,-0.0037517005,0.022826303,-0.010809984,0.010839094,-0.019045055,0.0039254534,-0.0019465599,-0.003849208,0.016841829,0.041753832,0.0055880956,0.028029948,-0.015579596,-0.19757037,-0.00568336,0.008916952,0.0068771644,-0.0164718,-0.014588332,0.02028174,-0.010250899,0.013381657,-0.02878137,-0.02667973,-0.0124621885,-0.020258686,0.014599721,-0.01862148,-0.034265585,0.03516502,0.022063864,0.00889546,0.018550787,0.002707751,0.024197863,-0.020962179,0.009396679,-0.003412773,0.034959402,0.007852238,-0.0041213525,0.02323511,-0.0050302115,-0.02926886,-0.016865391,-0.018900117,-0.018400006,0.040236387,0.014942313,0.006501869,-0.014131685,-0.0056511024,0.005678792,0.0013946629,0.002948981,0.020411655,0.0013781617,0.009174046,-0.009177555,0.0050871954,-0.029034376,-0.013464165,0.014803716,0.006874661,-0.008407248,0.0020233295,-0.003567856,-0.004071702,-0.017782187,0.007261173,0.0038184368,-0.0032931722,-0.0042817043,0.014546772,-0.0022774905,-0.12974344,-0.00858466,0.025082046,0.006956095,0.0063842037,0.015548625,0.02163282,0.024472121,0.0266