019dbbbb-50a3-74da-603b-1b1bb67b0db7	Double Leg Butt Kick	push	beginner	compound	body only	{quadriceps}	{abductors,adductors,calves,glutes,hamstrings}	{"Begin standing with your knees slightly bent.","Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."}	{Double_Leg_Butt_Kick/0.jpg,Double_Leg_Butt_Kick/1.jpg}	plyometrics	[0.027832901,0.01949499,-0.0023622867,-0.045349713,-0.020287992,-0.010822145,0.012529859,-0.0047580646,-0.008955671,0.006276184,-0.014331748,-0.0059560025,-0.0035532285,-0.022135807,0.12783922,-0.0110583035,0.021754762,0.012709857,0.01274425,-0.014980904,0.0028785693,0.010801191,-0.017640257,-0.024198005,0.007998165,-0.0072275256,0.039620195,-0.0031079731,0.037850965,-0.004810115,-0.004168502,-0.00017785681,0.029167334,0.013303065,0.028024452,0.0077129593,0.022130445,-0.0009071749,-0.010371008,0.0013193408,0.0020330579,-0.0014407259,-0.017701747,0.008924335,-0.014665246,0.023214854,-0.0057519632,0.042179648,0.011051396,0.04527313,0.0021390088,0.00041858293,0.01193321,-0.18294139,0.0077876183,-0.022661814,-0.0032075327,-0.024991326,-0.011855714,0.0022693614,0.0037328878,0.0241831,-0.009474349,-0.013381504,-0.01681466,0.009354921,-0.008777924,-0.014002417,-0.019931091,0.011524137,0.014867939,-0.023617746,0.000349092,-0.0032993108,-0.004638421,-0.018541202,0.013498265,0.016525181,0.0011421243,0.03306564,0.009841688,0.002174846,0.002556309,-0.037158184,0.015148116,-0.02001922,-0.009202494,0.011816852,-0.004371903,-0.011940753,0.0032892595,-0.012209086,-0.0031004911,0.0068298383,0.00901424,0.00855954,0.003779993,-0.0031638052,-0.004286097,0.019168582,-0.026826719,-0.024536047,0.0012928719,-0.0043866667,0.015698077,-0.009304032,-0.009496023,0.0038524638,0.014580193,-0.012350783,0.0009242823,-0.00212